`include "timescale.v"

module tb_spi_top();

// === Global Sync Signal ===
reg llm_go_signal = 1;


  reg         clk;
  reg         rst;
  wire [31:0] adr;
  wire [31:0] dat_i, dat_o;
  wire        we;
  wire  [3:0] sel;
  wire        stb;
  wire        cyc;
  wire        ack;
  wire        err;
  wire        int_1;

  wire  [7:0] ss;
  wire        sclk;
  wire        mosi;
  wire        miso;

  reg  [31:0] q;
  reg  [31:0] q1;
  reg  [31:0] q2;
  reg  [31:0] q3;
  reg  [31:0] result;
integer file_mantra;
  parameter SPI_RX_0   = 5'h0;
  parameter SPI_RX_1   = 5'h4;
  parameter SPI_RX_2   = 5'h8;
  parameter SPI_RX_3   = 5'hc;
  parameter SPI_TX_0   = 5'h0;
  parameter SPI_TX_1   = 5'h4;
  parameter SPI_TX_2   = 5'h8;
  parameter SPI_TX_3   = 5'hc;
  parameter SPI_CTRL   = 5'h10;
  parameter SPI_DIVIDE = 5'h14;
  parameter SPI_SS     = 5'h18;

  // Generate clock
  always #5 clk = ~clk;


  // Wishbone master model
  wb_master_model #(32, 32) i_wb_master (
    .clk(clk), .rst(rst),
    .adr(adr), .din(dat_i), .dout(dat_o),
    .cyc(cyc), .stb(stb), .we(we), .sel(sel), .ack(ack), .err(err), .rty(1'b0)
  );

  // SPI master core
  spi_top i_spi_top (
    .wb_clk_i(clk), .wb_rst_i(rst), 
    .wb_adr_i(adr[4:0]), .wb_dat_i(dat_o), .wb_dat_o(dat_i), 
    .wb_sel_i(sel), .wb_we_i(we), .wb_stb_i(stb), 
    .wb_cyc_i(cyc), .wb_ack_o(ack), .wb_err_o(err), .wb_int_o(int_1),
    .ss_pad_o(ss), .sclk_pad_o(sclk), .mosi_pad_o(mosi), .miso_pad_i(miso) 
  );

  // SPI slave model
  spi_slave_model i_spi_slave (
    .rst(rst), .ss(ss[0]), .sclk(sclk), .mosi(mosi), .miso(miso)
  );

//  integer f;
  initial begin
      $display("\nstatus: %t Testbench started\n\n", $time);

      $dumpfile("bench.vcd");
      $dumpvars(1, tb_spi_top);
      $dumpvars(1, tb_spi_top.i_spi_slave);

      // Initial values
      clk = 0;
	//  f = $fopen("output.txt");
  //    $fwrite(f, "time,dat_o\n");


      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b0;

      result = 32'h0;

      // Reset system
      rst = 1'b0; // negate reset
    wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB
     // Initial values
      clk = 0;
	//  f = $fopen("output.txt");
  //    $fwrite(f, "time,dat_o\n");


      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b0;

      result = 32'h0;

      // Reset system
      rst = 1'b0; // neg
      #2;
      rst = 1'b1; // assert reset
      repeat(20) @(posedge clk);
      rst = 1'b0; // negate reset

      $display("status: %t done reset", $time);

      @(posedge clk);

      // Program core
      i_wb_master.wb_write(0, SPI_DIVIDE, 32'h00); // set devider register
      i_wb_master.wb_write(0, SPI_TX_0, 32'h5a);   // set tx register to 0x5a
      i_wb_master.wb_write(0, SPI_CTRL, 32'h208);   // set 8 bit transfer
      i_wb_master.wb_write(0, SPI_SS, 32'h01);     // set ss 0

      $display("status: %t programmed registers", $time);

      i_wb_master.wb_cmp(0, SPI_DIVIDE, 32'h00);   // verify devider register
      i_wb_master.wb_cmp(0, SPI_TX_0, 32'h5a);     // verify tx register
      i_wb_master.wb_cmp(0, SPI_CTRL, 32'h208);     // verify tx register
      i_wb_master.wb_cmp(0, SPI_SS, 32'h01);       // verify ss register

      $display("status: %t verified registers", $time);

      i_spi_slave.rx_negedge = 1'b1;
      i_spi_slave.tx_negedge = 1'b0;
      i_spi_slave.data[31:0] = 32'ha5967e5a;
      i_wb_master.wb_write(0, SPI_CTRL, 32'h308);   // set 8 bit transfer, start transfer

      $display("status: %t generate transfer:  8 bit, msb first, tx posedge, rx negedge", $time);

      // Check bsy bit
      i_wb_master.wb_read(0, SPI_CTRL, q);
      while (q[8])
        i_wb_master.wb_read(1, SPI_CTRL, q);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      if (i_spi_slave.data[7:0] == 8'h5a && q == 32'h000000a5)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b1;
      i_wb_master.wb_write(0, SPI_TX_0, 32'ha5);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h408);   // set 8 bit transfer, tx negedge
      i_wb_master.wb_write(0, SPI_CTRL, 32'h508);   // set 8 bit transfer, tx negedge, start transfer

      $display("status: %t generate transfer:  8 bit, msb first, tx negedge, rx posedge", $time);

      // Check bsy bit
      i_wb_master.wb_read(0, SPI_CTRL, q);
      while (q[8])
        i_wb_master.wb_read(1, SPI_CTRL, q);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      if (i_spi_slave.data[7:0] == 8'ha5 && q == 32'h00000096)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b1;
      i_wb_master.wb_write(0, SPI_TX_0, 32'h5aa5);
      i_wb_master.wb_write(0, SPI_CTRL, 32'hc10);   // set 16 bit transfer, tx negedge, lsb
      i_wb_master.wb_write(0, SPI_CTRL, 32'hd10);   // set 16 bit transfer, tx negedge, start transfer

      $display("status: %t generate transfer: 16 bit, lsb first, tx negedge, rx posedge", $time);

      // Check bsy bit
      i_wb_master.wb_read(0, SPI_CTRL, q);
      while (q[8])
        i_wb_master.wb_read(1, SPI_CTRL, q);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      if (i_spi_slave.data[15:0] == 16'ha55a && q == 32'h00005a7e)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b1;
      i_spi_slave.tx_negedge = 1'b0;
      i_wb_master.wb_write(0, SPI_TX_0, 32'h76543210);
      i_wb_master.wb_write(0, SPI_TX_1, 32'hfedcba98);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h1a40);   // set 64 bit transfer, rx negedge, lsb
      i_wb_master.wb_write(0, SPI_CTRL, 32'h1b40);   // set 64 bit transfer, rx negedge, start transfer

      $display("status: %t generate transfer: 64 bit, lsb first, tx posedge, rx negedge", $time);

      // Check bsy bit
      i_wb_master.wb_read(0, SPI_CTRL, q);
      while (q[8])
        i_wb_master.wb_read(1, SPI_CTRL, q);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;
      i_wb_master.wb_read(1, SPI_RX_1, q1);
      result = result + q1;

      if (i_spi_slave.data == 32'h195d3b7f && q == 32'h5aa5a55a && q1 == 32'h76543210)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b1;
      i_wb_master.wb_write(0, SPI_TX_0, 32'hccddeeff);
      i_wb_master.wb_write(0, SPI_TX_1, 32'h8899aabb);
      i_wb_master.wb_write(0, SPI_TX_2, 32'h44556677);
      i_wb_master.wb_write(0, SPI_TX_3, 32'h00112233);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h400);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h500);

      $display("status: %t generate transfer: 128 bit, msb first, tx posedge, rx negedge", $time);

      // Check bsy bit
      i_wb_master.wb_read(0, SPI_CTRL, q);
      while (q[8])
        i_wb_master.wb_read(1, SPI_CTRL, q);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;
      i_wb_master.wb_read(1, SPI_RX_1, q1);
      result = result + q1;
      i_wb_master.wb_read(1, SPI_RX_2, q2);
      result = result + q2;
      i_wb_master.wb_read(1, SPI_RX_3, q3);
      result = result + q3;

      if (i_spi_slave.data == 32'hccddeeff && q == 32'h8899aabb && q1 == 32'h44556677 && q2 == 32'h00112233 && q3 == 32'h195d3b7f)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b0;
      i_spi_slave.tx_negedge = 1'b1;
      i_wb_master.wb_write(0, SPI_TX_0, 32'haa55a5a5);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h1420);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h1520);

      $display("status: %t generate transfer: 32 bit, msb first, tx negedge, rx posedge, ie", $time);

      // Check interrupt signal
      while (!int_1)
        @(posedge clk);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      @(posedge clk);
      if (!int_1 && i_spi_slave.data == 32'haa55a5a5 && q == 32'hccddeeff)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b1;
      i_spi_slave.tx_negedge = 1'b0;
      i_wb_master.wb_write(0, SPI_TX_0, 32'h01248421);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h3220);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h3320);

      $display("status: %t generate transfer: 32 bit, msb first, tx posedge, rx negedge, ie, ass", $time);

      while (!int_1)
        @(posedge clk);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      @(posedge clk);
      if (!int_1 && i_spi_slave.data == 32'h01248421 && q == 32'haa55a5a5)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      i_spi_slave.rx_negedge = 1'b1;
      i_spi_slave.tx_negedge = 1'b0;
      i_wb_master.wb_write(0, SPI_TX_0, 32'h1);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h3201);
      i_wb_master.wb_write(0, SPI_CTRL, 32'h3301);

      $display("status: %t generate transfer: 1 bit, msb first, tx posedge, rx negedge, ie, ass", $time);

      while (!int_1)
        @(posedge clk);

      i_wb_master.wb_read(1, SPI_RX_0, q);
      result = result + q;

      @(posedge clk);
      if (!int_1 && i_spi_slave.data == 32'h02490843 && q == 32'h0)
        $display("status: %t transfer completed: ok", $time);
      else
        $display("status: %t transfer completed: nok", $time);

      $display("\n\nstatus: %t Testbench done", $time);

      #25000; // wait 25us

      $display("report (%h)", (result ^ 32'h2e8b36ab) + 32'hdeaddead);
      $display("exit (%h)", result ^ 32'h2e8b36ab);
	  if (file_mantra != 0) $fclose(file_mantra);
      $finish;
    end
  //  always @(posedge clk)
 //   $fwrite(f, "%0d, %0x\n", $time,dat_o);

	  ///////////////////added

        initial begin
          file_mantra = $fopen("output.txt");//added
          $fwrite(file_mantra, "time, ");
      // $fwrite(file_mantra, "adr,");
      $fwrite(file_mantra, "dat_o,");
      // $fwrite(file_mantra, "cyc,");
      // $fwrite(file_mantra, "stb,");
      // $fwrite(file_mantra, "we,");
      // $fwrite(file_mantra, "sel,");
      // $fwrite(file_mantra, "dat_i,");
      // $fwrite(file_mantra, "ack,");
      // $fwrite(file_mantra, "err,");
      // $fwrite(file_mantra, "int_1,");
      // $fwrite(file_mantra, "ss,");
      // $fwrite(file_mantra, "sclk,");
      // $fwrite(file_mantra, "mosi,");
      // $fwrite(file_mantra, "miso,");

          $fwrite(file_mantra, "\n");//added
          forever begin
            //#5
            #1
            $fwrite(file_mantra, "%0d, ", $time);
        // $fwrite(file_mantra, "%h, ", adr);
        $fwrite(file_mantra, "%h, ", dat_o);
        // $fwrite(file_mantra, "%h, ", cyc);
        // $fwrite(file_mantra, "%h, ", stb);
        // $fwrite(file_mantra, "%h, ", we);
        // $fwrite(file_mantra, "%h, ", sel);
        // $fwrite(file_mantra, "%h, ", dat_i);
        // $fwrite(file_mantra, "%h, ", ack);
        // $fwrite(file_mantra, "%h, ", err);
        // $fwrite(file_mantra, "%h, ", int_1);
        // $fwrite(file_mantra, "%h, ", ss);
        // $fwrite(file_mantra, "%h, ", sclk);
        // $fwrite(file_mantra, "%h, ", mosi);
        // $fwrite(file_mantra, "%h, ", miso);

            $fwrite(file_mantra, "\n");
          end
        end

	  // initial begin
    // wait(llm_go_signal == 0); // [Auto] Handover from LLM to Original TB

// #2000000
// $finish;
// end


// ============================================
// === LLM Enhanced Stimuli (Phase 1) ===
initial begin
    // [Auto-Moved Vars]
        integer i;
        reg [31:0] read_data;
        reg [31:0] temp_val;

    // 1. DECLARE VARIABLES FIRST




    // 2. THEN WAIT for original tests
    // The stimuli runs BEFORE the original testbench, waiting for the go signal.
    wait(llm_go_signal == 1);

    $display("LLM: Starting Mutation Tests...");

    // ---------------------------------------------------------
    // Test 1: Boundary Condition - 1-bit Transfer
    // Target: Counter logic, boundary checks
    // ---------------------------------------------------------
    $display("LLM: Test 1 - 1-bit Transfer");
    // Setup Slave: Sends 1
    i_spi_slave.rx_negedge = 1'b1; 
    i_spi_slave.tx_negedge = 1'b0;
    i_spi_slave.data = 32'h00000001; 

    // Setup Master
    i_wb_master.wb_write(1, SPI_DIVIDE, 32'h0004); 
    i_wb_master.wb_write(1, SPI_SS, 32'h01);       
    i_wb_master.wb_write(1, SPI_TX_0, 32'h00000000); 

    // CTRL: ASS(1) | RX_NEG(1) | GO(1) | LEN(0) -> 0x2300
    // LEN=0 means 1 bit length
    i_wb_master.wb_write(1, SPI_CTRL, 32'h00002300);

    // Wait for busy clear
    read_data = 32'h00000100; 
    while(read_data[8]) begin
        i_wb_master.wb_read(1, SPI_CTRL, read_data);
    end

    // Check RX
    i_wb_master.wb_read(1, SPI_RX_0, read_data);
    if ((read_data & 32'h1) !== 1'b1) 
        $display("LLM: Test 1 Failed. Expected 1, got %h", read_data);
    else 
        $display("LLM: Test 1 Passed.");

    // ---------------------------------------------------------
    // Test 2: Odd Length - 5 bits, LSB First
    // Target: Shift logic, LSB/MSB muxing, odd counter values
    // ---------------------------------------------------------
    $display("LLM: Test 2 - 5-bit Transfer, LSB First");
    // Slave data: Top 5 bits are 11010 (0x1A). Slave shifts MSB out.
    // Sequence: 1, 1, 0, 1, 0.
    i_spi_slave.data = 32'hD0000000; 
    i_wb_master.wb_write(1, SPI_TX_0, 32'h00000015);

    // CTRL: ASS(1) | LSB(1) | RX_NEG(1) | GO(1) | LEN(4) -> 0x2B04
    // LEN=4 means 5 bits length
    i_wb_master.wb_write(1, SPI_CTRL, 32'h00002B04);

    read_data = 32'h00000100;
    while(read_data[8]) i_wb_master.wb_read(1, SPI_CTRL, read_data);

    i_wb_master.wb_read(1, SPI_RX_0, read_data);
    // Master samples LSB first: 1, 1, 0, 1, 0 -> 01011 (0x0B)
    if ((read_data & 32'h1F) !== 32'h0B) 
        $display("LLM: Test 2 Failed. Expected 0x0B, got %h", read_data);
    else 
        $display("LLM: Test 2 Passed.");

    // ---------------------------------------------------------
    // Test 3: Max Length (128 bits)
    // Target: Full buffer usage, counter overflow/wrap
    // ---------------------------------------------------------
    $display("LLM: Test 3 - 128-bit Transfer");
    i_wb_master.wb_write(1, SPI_TX_0, 32'h11111111);
    i_wb_master.wb_write(1, SPI_TX_1, 32'h22222222);
    i_wb_master.wb_write(1, SPI_TX_2, 32'h33333333);
    i_wb_master.wb_write(1, SPI_TX_3, 32'h44444444);

    // CTRL: ASS(1) | RX_NEG(1) | GO(1) | LEN(127) -> 0x237F
    i_wb_master.wb_write(1, SPI_CTRL, 32'h0000237F);

    read_data = 32'h00000100;
    while(read_data[8]) i_wb_master.wb_read(1, SPI_CTRL, read_data);

    // Verify Slave received TX_0 (Last 32 bits shifted in by Master)
    // Master sends MSB first (TX_3 -> TX_2 -> TX_1 -> TX_0)
    // Slave shifts left. Last 32 bits received are TX_0.
    if (i_spi_slave.data !== 32'h11111111) 
        $display("LLM: Test 3 Failed. Slave data %h != 11111111", i_spi_slave.data);
    else 
        $display("LLM: Test 3 Passed.");

    // ---------------------------------------------------------
    // Test 4: Interrupt Generation
    // Target: Control flow, interrupt logic
    // ---------------------------------------------------------
    $display("LLM: Test 4 - Interrupt Test");
    // CTRL: ASS(1) | IE(1) | RX_NEG(1) | GO(1) | LEN(7) -> 0x3307
    i_wb_master.wb_write(1, SPI_CTRL, 32'h00003307);

    i = 0;
    while (int_1 == 0 && i < 2000) begin
        @(posedge clk);
        i = i + 1;
    end

    if (int_1) 
        $display("LLM: Test 4 Passed. Interrupt received.");
    else 
        $display("LLM: Test 4 Failed. Timeout waiting for interrupt.");

    // Clear interrupt by reading CTRL
    i_wb_master.wb_read(1, SPI_CTRL, read_data);

    // ---------------------------------------------------------
    // Test 5: Divider 0 (Fastest)
    // Target: Clock generation logic, edge cases
    // ---------------------------------------------------------
    $display("LLM: Test 5 - Divider 0");
    i_wb_master.wb_write(1, SPI_DIVIDE, 32'h0000);
    i_wb_master.wb_write(1, SPI_TX_0, 32'hA5A5A5A5);
    // 8 bits
    i_wb_master.wb_write(1, SPI_CTRL, 32'h00002307);

    read_data = 32'h00000100;
    while(read_data[8]) i_wb_master.wb_read(1, SPI_CTRL, read_data);
    $display("LLM: Test 5 Passed.");

    // ---------------------------------------------------------
    // Test 6: Manual Slave Select
    // Target: Output logic, blocking/non-blocking assignments
    // ---------------------------------------------------------
    $display("LLM: Test 6 - Manual SS");
    // Disable ASS (bit 13 = 0). SS = 2.
    i_wb_master.wb_write(1, SPI_SS, 32'h00000002);
    #100;
    // Check ss pad. Expect ~2 = FD (active low).
    if (ss !== 8'hFD) 
        $display("LLM: Test 6 Failed. SS expected FD, got %h", ss);
    else 
        $display("LLM: Test 6 Passed.");

    // Restore SS for original TB
    i_wb_master.wb_write(1, SPI_SS, 32'h01);

    // ---------------------------------------------------------
    // Handover
    // ---------------------------------------------------------
    $display("LLM: Tests Complete. Handing over to Original TB...");
    llm_go_signal = 0;
end
// ============================================


// === Global Watchdog ===

// === Global Safety Watchdog (Injected) ===
initial begin
    #200000;
    $display("\n[Watchdog] Timeout triggered at %t!", $time);
    if (file_mantra != 0) $fclose(file_mantra);
    $finish;
end

endmodule

records.buggy_rtl:
module spi_clgen
(
  clk_in,
  rst,
  go,
  enable,
  last_clk,
  divider,
  clk_out,
  pos_edge,
  neg_edge
);

  parameter Tp = 1;
  input clk_in;
  input rst;
  input enable;
  input go;
  input last_clk;
  input [16-1:0] divider;
  output clk_out;
  output pos_edge;
  output neg_edge;
  reg clk_out;
  reg pos_edge;
  reg neg_edge;
  reg [16-1:0] cnt;
  wire cnt_zero;
  wire cnt_one;
  assign cnt_zero = cnt == { 16{ 1'b0 } };
  assign cnt_one = cnt == { { 16 - 1{ 1'b0 } }, 1'b1 };

  always @(posedge clk_in or posedge rst) begin
    if(rst) cnt <= #Tp { 16{ 1'b1 } }; 
