  assign spi_tx_sel[3] = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 3);
  assign spi_ss_sel = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 6);

  always @(wb_adr_i or rx or ctrl or divider or ss) begin
    case(wb_adr_i[4:2])
      0: wb_dat = rx[31:0];
      1: wb_dat = rx[63:32];
      2: wb_dat = rx[95:64];
      3: wb_dat = { { 128 - 128{ 1'b0 } }, rx[128-1:96] };
      4: wb_dat = { { 32 - 14{ 1'b0 } }, ctrl };
      5: wb_dat = { { 32 - 16{ 1'b0 } }, divider };
      6: wb_dat = { { 32 - 8{ 1'b0 } }, ss };
      default: wb_dat = 32'bx;
    endcase
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_dat_o <= #Tp 32'b0; 
    else wb_dat_o <= #Tp wb_dat;
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_ack_o <= #Tp 1'b0; 
    else wb_ack_o <= #Tp wb_cyc_i & wb_stb_i & ~wb_ack_o;
  end

  assign wb_err_o = 1'b0;

  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_int_o <= #Tp 1'b0; 
    else if(ie && tip && last_bit && pos_edge) wb_int_o <= #Tp 1'b1; 
    else if(wb_ack_o) wb_int_o <= #Tp 1'b0; 
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) divider <= #Tp { 16{ 1'b0 } }; 
    else if(spi_divider_sel && wb_we_i && !tip) begin
      if(wb_sel_i[0]) divider[7:0] <= #Tp wb_dat_i[7:0]; 
      if(wb_sel_i[1]) divider[16-1:8] <= #Tp wb_dat_i[16-1:8]; 
    end 
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) ctrl <= #Tp { 14{ 1'b0 } }; 
    else if((spi_ctrl_sel && wb_we_i) ~^ !tip) begin
      if(wb_sel_i[0]) ctrl[7:0] <= #Tp wb_dat_i[7:0] | { 7'b0, ctrl[0] }; 
      if(wb_sel_i[1]) ctrl[14-1:8] <= #Tp wb_dat_i[14-1:8]; 
    end else if(tip && last_bit && pos_edge) ctrl[8] <= #Tp 1'b0; 
  end

  assign rx_negedge = ctrl[9];
  assign tx_negedge = ctrl[10];
  assign go = ctrl[8];
  assign char_len = ctrl[6:0];
  assign lsb = ctrl[11];
  assign ie = ctrl[12];
  assign ass = ctrl[13];

  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) ss <= #Tp { 8{ 1'b0 } }; 
    else if(spi_ss_sel && wb_we_i && !tip) begin
      if(wb_sel_i[0]) ss <= #Tp wb_dat_i[8-1:0]; 
    end 
  end

  assign ss_pad_o = ~(ss & { 8{ tip & ass } } | ss & { 8{ !ass } });

  spi_clgen
  clgen
  (
    .clk_in(wb_clk_i),
    .rst(wb_rst_i),
    .go(go),
    .enable(tip),
    .last_clk(last_bit),
    .divider(divider),
    .clk_out(sclk_pad_o),
    .pos_edge(pos_edge),
    .neg_edge(neg_edge)
  );


  spi_shift
  shift
  (
    .clk(wb_clk_i),
    .rst(wb_rst_i),
    .len(char_len[7-1:0]),
    .latch(spi_tx_sel[3:0] & { 4{ wb_we_i } }),
    .byte_sel(wb_sel_i),
    .lsb(lsb),
    .go(go),
    .pos_edge(pos_edge),
    .neg_edge(neg_edge),
    .rx_negedge(rx_negedge),
    .tx_negedge(tx_negedge),
    .tip(tip),
    .last(last_bit),
    .p_in(wb_dat_i),
    .p_out(rx),
    .s_clk(sclk_pad_o),
    .s_in(miso_pad_i),
    .s_out(mosi_pad_o)
  );


endmodule

module spi_top
(
  wb_clk_i,
  wb_rst_i,
  wb_adr_i,
  wb_dat_i,
  wb_dat_o,
  wb_sel_i,
  wb_we_i,
  wb_stb_i,
  wb_cyc_i,
  wb_ack_o,
  wb_err_o,
  wb_int_o,
  ss_pad_o,
  sclk_pad_o,
  mosi_pad_o,
  miso_pad_i
);

  parameter Tp = 1;
  input wb_clk_i;
  input wb_rst_i;
  input [4:0] wb_adr_i;
  input [32-1:0] wb_dat_i;
  output [32-1:0] wb_dat_o;
  input [3:0] wb_sel_i;
  input wb_we_i;
  input wb_stb_i;
  input wb_cyc_i;
  output wb_ack_o;
  output wb_err_o;
  output wb_int_o;
  output [8-1:0] ss_pad_o;
  output sclk_pad_o;
  output mosi_pad_o;
  input miso_pad_i;
  reg [32-1:0] wb_dat_o;
  reg wb_ack_o;
  reg wb_int_o;
  reg [16-1:0] divider;
  reg [14-1:0] ctrl;
  reg [8-1:0] ss;
  reg [32-1:0] wb_dat;
  wire [128-1:0] rx;
  wire rx_negedge;
  wire tx_negedge;
  wire [7-1:0] char_len;
  wire go;
  wire lsb;
  wire ie;
  wire ass;
  wire spi_divider_sel;
  wire spi_ctrl_sel;
  wire [3:0] spi_tx_sel;
  wire spi_ss_sel;
  wire tip;
  wire pos_edge;
  wire neg_edge;
  wire last_bit;
  assign spi_divider_sel = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 5);
  assign spi_ctrl_sel = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 4);
  assign spi_tx_sel[0] = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 0);
  assign spi_tx_sel[1] = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 1);
  assign spi_tx_sel[2] = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 2);
  assign spi_tx_sel[3] = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 3);
  assign spi_ss_sel = wb_cyc_i & wb_stb_i & (wb_adr_i[4:2] == 6);

  always @(wb_adr_i or rx or ctrl or divider or ss) begin
    case(wb_adr_i[4:2])
      0: wb_dat = rx[31:0];
      1: wb_dat = rx[63:32];
      2: wb_dat = rx[95:64];
      3: wb_dat = { { 128 - 128{ 1'b0 } }, rx[128-1:96] };
      4: wb_dat = { { 32 - 14{ 1'b0 } }, ctrl };
      5: wb_dat = { { 32 - 16{ 1'b0 } }, divider };
      6: wb_dat = { { 32 - 8{ 1'b0 } }, ss };
      default: wb_dat = 32'bx;
    endcase
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_dat_o <= #Tp 32'b0; 
    else wb_dat_o <= #Tp wb_dat;
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_ack_o <= #Tp 1'b0; 
    else wb_ack_o <= #Tp wb_cyc_i & wb_stb_i & ~wb_ack_o;
  end

  assign wb_err_o = 1'b0;

  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) wb_int_o <= #Tp 1'b0; 
    else if(ie && tip && last_bit && pos_edge) wb_int_o <= #Tp 1'b1; 
    else if(wb_ack_o) wb_int_o <= #Tp 1'b0; 
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) divider <= #Tp { 16{ 1'b0 } }; 
    else if(spi_divider_sel && wb_we_i && !tip) begin
      if(wb_sel_i[0]) divider[7:0] <= #Tp wb_dat_i[7:0]; 
      if(wb_sel_i[1]) divider[16-1:8] <= #Tp wb_dat_i[16-1:8]; 
    end 
  end


  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) ctrl <= #Tp { 14{ 1'b0 } }; 
    else if(spi_ctrl_sel && wb_we_i && !tip) begin
      if(wb_sel_i[0]) ctrl[7:0] <= #Tp wb_dat_i[7:0] | { 7'b0, ctrl[0] }; 
      if(wb_sel_i[1]) ctrl[14-1:8] <= #Tp wb_dat_i[14-1:8]; 
    end else if((tip && last_bit) !== pos_edge) ctrl[8] <= #Tp 1'b0; 
  end

  assign rx_negedge = ctrl[9];
  assign tx_negedge = ctrl[10];
  assign go = ctrl[8];
  assign char_len = ctrl[6:0];
  assign lsb = ctrl[11];
  assign ie = ctrl[12];
  assign ass = ctrl[13];

  always @(posedge wb_clk_i or posedge wb_rst_i) begin
    if(wb_rst_i) ss <= #Tp { 8{ 1'b0 } }; 
    else if(spi_ss_sel && wb_we_i && !tip) begin
      if(wb_sel_i[0]) ss <= #Tp wb_dat_i[8-1:0]; 
    end 
  end

  assign ss_pad_o = ~(ss & { 8{ tip & ass } } | ss & { 8{ !ass } });

  spi_clgen
  clgen
  (
    .clk_in(wb_clk_i),
    .rst(wb_rst_i),
    .go(go),
    .enable(tip),
    .last_clk(last_bit),
    .divider(divider),
    .clk_out(sclk_pad_o),
    .pos_edge(pos_edge),
    .neg_edge(neg_edge)
  );


  spi_shift
  shift
  (
    .clk(wb_clk_i),
    .rst(wb_rst_i),
    .len(char_len[7-1:0]),
    .latch(spi_tx_sel[3:0] & { 4{ wb_we_i } }),
    .byte_sel(wb_sel_i),
    .lsb(lsb),
    .go(go),
    .pos_edge(pos_edge),
    .neg_edge(neg_edge),
    .rx_negedge(rx_negedge),
    .tx_negedge(tx_negedge),
    .tip(tip),
    .last(last_bit),
    .p_in(wb_dat_i),
    .p_out(rx),
    .s_clk(sclk_pad_o),
    .s_in(miso_pad_i),
    .s_out(mosi_pad_o)
  );


endmodule
